sys_script_include.script:
var MedicationUtils = Class.create();
MedicationUtils.prototype = {
    initialize: function() {
    },
      getAllMedications: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_medication_name') + ';' + gr.getValue('u_dosage') + '\n';
        }
        return result || false;
    },

    // 2. Get active medications (assuming field 'u_status' = 'Active')
    getActiveMedications: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_status', 'Active');
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_medication_name') + ';' + gr.getValue('u_dosage') + '\n';
        }
        return result || false;
    },

    // 3. Get medication by name
    getMedicationByName: function (patientId, medicationName) {
        var result = '';
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_medication_name', medicationName);
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_medication_name') + ';' + gr.getValue('u_dosage') + ';' + gr.getValue('u_frequency') + '\n';
        }
        return result || false;
    },

    // 4. Get medication history (assumes field u_end_date exists)
    getMedicationHistory: function (patientId) {
        var result = '';
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addNotNullQuery('u_end_date');
        gr.query();
        while (gr.next()) {
            result += gr.getValue('u_medication_name') + ';' + gr.getValue('u_start_date') + ' to ' + gr.getValue('u_end_date') + '\n';
        }
        return result || false;
    },

    // 5. Check if a medication is currently prescribed
    isMedicationPrescribed: function (patientId, medicationName) {
        var gr = new GlideRecord('u_medication');
        gr.addQuery('u_patient_id.u_patient_id', patientId);
        gr.addQuery('u_medication_name', medicationName);
        gr.addNullQuery('u_end_date'); // no end date means it's still prescribed
        gr.query();
        return gr.hasNext();
    },
    type: 'MedicationUtils'
};
